cards.append(compact('zeng_yuan','曾原','曾原是槟城参与调查古九非命案的年轻警官，热诚坦率，也知道案件牵涉军方与国际交易，普通警方很难接近核心。他陪卫斯理去现场和殓房，对惨状同样激动，却没有只停留在同情，继续搜查嫌疑人的住所、核查酒店职位的来历，找出化名包勃者靠贿赂进入国宴的线索。他不愿轻易接受调查到此为止，听到卫斯理已经判断凶手是谁，立即主张将人绳之于法。包勃等人在小型飞机失事中丧生，照片被送来辨认，他主动请求继续追查，起初获准，后来又被上级告诫别多事；阿加酋长的车祸同样被压成无可疑案件。这些阻力使他不满，却没有把他写成能凭热血推翻组织的英雄。他还注意到青龙异常的旁敲侧击，试图向卫斯理报告，不知道其中保护朋友的用意。终局卡保留具体调查能力、程序理想和对权力干预的困惑，不赋予他主宰会全部情报或军方权限。演绎中，他能把模糊的不安落成可查的证据，也可能因越级求证而遭遇现实后果。','《瘟神》仍任警官，调查受上级限制，未能继续追索主宰会','主角','查明命案并将责任人带入可执行的司法程序','坦率热心，肯陪同现场调查，也敏感于证词和行为变化','证据指向强势组织时想继续查，上级阻止令他不满而困惑','有责任追索真相，也必须认清权限和证据缺口，不能以义愤代替事实',[ab('刑事调查','核查现场、酒店职员关系、住宅及照片身份，联系相关警务部门','权限受制于上级，不能凭职位读取外国或秘密组织全部档案'),ab('观察与报告','注意青龙问话的反常并把具体情况告诉有关者','不知道谈话背后全部动机，观察需核查不能自动判人有罪')],[ev('076',2296,2437,'青年警官和查案合作'),ev('076',3297,3405,'包勃身份调查及追责'),ev('076',3998,4055,'辨尸、追查受阻和观察青龙')],profile='investigator'))
cards.append(compact('ajia','阿加酋长','阿加酋长拥有一块产油领地，以跨国军火交易积聚财富，生活极其豪奢，却仍不满足已有地位。他用价值超过十亿美元的军备，换取斐将军推荐自己进入主宰会旁听的资格，希望从供应武器的人变成参与更大权力分配的人。象征资格的小盒子在机场被古九非偷走，他怒气冲冲地悬赏追索，既害怕秘密泄露，又不得不与卫斯理、青龙讨价还价。表面上无所不能的富豪，在被问到组织内部时显得惊惶，因为他只是有条件旁听的边缘人，失物还可能引来处罚。取得小盒子后，他没有因此安全，温宝裕等再次拿走其中玻璃身份物，随后他在赴机场的车祸中死亡；会议录音后来确认主宰会以惩戒名义处理了他。卡片保留其贪权、豪奢和交易手腕，也写清他并非所有战争的制造者，不能把流通过的军火总量算成个人火力。参战恢复最后可行动的身体，财富与联系人需现实渠道，不重置已失的旁听资格，更没有瘟神法力。','《瘟神》遭主宰会安排的车祸杀害；参战恢复最后可行动形态，组织资格已失','反派','把财富和军火生意转化为更高层权力与身份','豪奢倨傲，以报酬和地位影响他人，遇机密则谨慎退让','资格和秘密受威胁时会悬赏、追索及讨价还价，面对更大组织仍恐惧','昂贵的入场代价不等于真正拥有决策权，钱不能保证保密与人身安全',[ab('军火交易与谈判','在有现成政治、运输及付款渠道时撮合买卖并交换利益','需要组织与国家合作，不等于本人随身携带所有军火'),ab('悬赏和关系施压','利用财富、领事渠道与公众消息追索失物','会收到假线索，普通盗窃也能使计划失控，不能无限购买真相')],[ev('076',500,527,'身份、豪奢及特权受限'),ev('076',2999,3104,'资格交易与恐惧'),ev('076',3454,3472,'车祸死亡'),ev('076',4470,4487,'组织承认惩戒')],profile='expert',aliases=['阿加酋长']))
