cards.append(compact('fei_general','斐将军','斐将军是东南亚局势中的军事强人，致力扩张，曾与邻国的野心人物会面，使各方情报机构紧张。他已经是主宰会成员，却并不满足会议共同决定的边界，借推荐阿加酋长取得观察资格，换取大批军备，以增长自己的现实实力。交易的凭证很小，能够随身携带，他在国宴中通过接触把东西交出，手法利落，连古九非也未能及时取到真正目标。这一动作成为偷窃、追索与死亡连锁的起点。组织发现他收取好处并越过既定限制后，没有让个人野心继续扩张，最终开除他；公开消息显示他已经下台，却没有详细说明理由。卡片以失去权位后的军政人物为终局，不擅自补成死亡，也不默认他仍可号令原部队。他懂得利益交换和利用场合，却不能因此被写成理解每一步后果的全知策士。来源中姓氏偶作裴，应作为字形异文保存，不分建另一个将军；现实人物身份未明确，不配外部历史原型。新场景可以让他在旧关系和新限制之间继续争取位置，但恢复军权必须成为发生在剧情里的结果。','《瘟神》被主宰会开除并下台，死亡未确认，现役军权不得默认保留','反派','扩大军事与政治影响，使个人安排越过集体限制','擅利益交换和正式场合中的隐蔽转交，对扩张有持续欲望','地位受到限制时可能以私下交易争取资源，须承担被组织发现的代价','已有身份不保证可无限越界，交换利益也会制造可追索的证据',[ab('军政交易经验','以推荐、关系和军备交换推进个人扩张','终局失势，原军队与组织权限不自动随身'),ab('隐蔽交接','在国宴人群中快速转交小物，令扒手一度失去目标','只是人类手法和时机，无法保证不被观察或事后追查')],[ev('076',1339,1353,'国宴交接'),ev('076',2662,2748,'扩张与军火交易'),ev('076',3055,3085,'受益关系'),ev('076',4109,4128,'下台消息'),ev('076',4484,4487,'开除确认')],profile='expert',aliases=['裴将军（个别行异文）']))
cards.append(compact('baobo','包勃','包勃是在槟城使用的化名，真实姓名与个人身世不明。他以富裕住所和普通职业作掩护，曾贿赂酒店高级职员，临时取得国宴侍者领班的位置，实际为主宰会担任东南亚联络员。他需要阻止斐将军和阿加酋长的资格交易，选择借古九非的高超扒窃术完成回收，却以天命与神秘话术遮蔽真正目的，低估了被利用者的习惯。古九非没有拿到目标，反从他身上取走一卷记录人体实验的底片，令任务失败上又增加泄密风险。卫斯理据事态判断，包勃及同伴逼问、虐杀了古九非；随后警方在被清理过的住所找不到重要线索，他本人则和几名同行死于一次来历不明的小型飞机失事。主宰会录音确认处置了原联络员与手下，使其组织归属和死亡性质得到后续支持。卡片不把具体酷刑细节扩充为必定有效的技能，也不把神秘组织所有科技交给他。他是懂得潜伏和借用人手、又在失败后以暴力扩大错误的执行者，终局显示组织不会因其曾卖命而保护他。','《瘟神》在组织惩戒安排的小型飞机失事中死亡；参战恢复最后可行动形态，联络员权限已被替换','反派','完成秘密任务、保住自己在组织内的位置并追回泄漏资料','以职业掩护接近目标，借钱和假象借用别人的专长','任务失控后趋向逼迫和灭口，反而使事情扩大','借来的专长并非可完全控制的工具，清理现场也不能清除组织内部记录',[ab('潜伏、贿赂与接头','取得国宴职位，联系外部技术人员执行隐藏目的','需要可用渠道与对象信任；对手也会反过来取走物件'),ab('联络与暴力人手','与同行追索资料并实施强制行动，离开前清理住所线索','归属和死亡有会议支持，具体每项暴行动作未由独立目击完整重现；不赋予超常战力')],[ev('076',1340,1424,'古九非受利用并取走底片'),ev('076',3297,3346,'化名、掩护和凶手判断'),ev('076',3385,3398,'清理现场与归责'),ev('076',3998,4022,'死亡辨认及调查受阻'),ev('076',4470,4479,'组织惩戒确认')],profile='investigator'))
